import 'dart:convert';
import 'dart:io';

/// Screenshot-independent catalog index (`gameinfo/full-index.json.gz`).
///
/// Generated by `tools/full-index-gen` from the game trees alone. It provides
/// the ZIP universe (section, layer, size) and the disk-image hashes used for
/// exact PirateFinder matching. Screenshot state (`preview`, `status`, `kind`)
/// stays in the screenshot index; [CatalogBundle] merges both.
class FullIndex {
  FullIndex._(
    this.entries,
    this.bySection,
    this._byFingerprint,
    this.generatedBy,
    this.counts,
  );

  /// Empty index (missing/unreadable file), so the app degrades to the
  /// screenshot index exactly as before.
  factory FullIndex.empty() =>
      FullIndex._(const {}, const {}, const {}, '', const {});

  /// Loads `<gameinfoDir>/full-index.json.gz`. Missing files yield an empty
  /// index plus a [warnings] note; parse errors are reported there too.
  factory FullIndex.load(String gameinfoDir, {List<String>? warnings}) {
    if (gameinfoDir.trim().isEmpty) return FullIndex.empty();
    final file = File('$gameinfoDir/full-index.json.gz');
    if (!file.existsSync()) return FullIndex.empty();
    try {
      final map = jsonDecode(
        utf8.decode(gzip.decode(file.readAsBytesSync())),
      ) as Map<String, dynamic>;
      final rawEntries =
          (map['entries'] as Map<String, dynamic>?) ??
          const <String, dynamic>{};
      final entries = <String, FullIndexEntry>{};
      final bySection = <String, Map<String, FullIndexEntry>>{};
      final byFingerprint = <String, FullIndexEntry>{};
      rawEntries.forEach((rel, value) {
        final entry = FullIndexEntry.fromJson(
          rel,
          value as Map<String, dynamic>,
        );
        entries[rel] = entry;
        bySection.putIfAbsent(entry.section, () => {})[rel] = entry;
        if (entry.fingerprint.isNotEmpty) {
          byFingerprint.putIfAbsent(entry.fingerprint, () => entry);
        }
      });
      return FullIndex._(
        entries,
        bySection,
        byFingerprint,
        (map['tool'] ?? '').toString(),
        (map['counts'] as Map<String, dynamic>?) ?? const {},
      );
    } catch (e) {
      warnings?.add('Full index: parse error: $e');
      return FullIndex.empty();
    }
  }

  final Map<String, FullIndexEntry> entries;

  /// Entries grouped by section (`cracked`, `pd`, `utils`, `magazine`,
  /// `falcon`), keyed by rel ZIP path.
  final Map<String, Map<String, FullIndexEntry>> bySection;

  final Map<String, FullIndexEntry> _byFingerprint;
  final String generatedBy;
  final Map<String, dynamic> counts;

  bool get isEmpty => entries.isEmpty;

  FullIndexEntry? operator [](String rel) => entries[rel];

  List<Map<String, dynamic>> hashesForRel(String rel) =>
      entries[rel]?.hashes ?? const [];

  List<Map<String, dynamic>> hashesForFingerprint(String fingerprint) =>
      _byFingerprint[fingerprint]?.hashes ?? const [];
}

/// One ZIP entry of the full index.
class FullIndexEntry {
  FullIndexEntry({
    required this.rel,
    required this.section,
    required this.name,
    required this.size,
    required this.mtime,
    required this.layer,
    required this.fingerprint,
    required this.members,
    required this.hashes,
  });

  factory FullIndexEntry.fromJson(String rel, Map<String, dynamic> json) {
    final hashes = <Map<String, dynamic>>[];
    final members = <FullIndexMember>[];
    for (final raw in (json['members'] as List<dynamic>?) ?? const []) {
      final member = FullIndexMember.fromJson(raw as Map<String, dynamic>);
      members.add(member);
      hashes.addAll(member.hashes);
    }
    return FullIndexEntry(
      rel: rel,
      section: (json['section'] ?? '').toString(),
      name: (json['name'] ?? rel.split('/').last).toString(),
      size: (json['size'] as num?)?.toInt() ?? 0,
      mtime: (json['mtime'] as num?)?.toInt() ?? 0,
      layer: (json['layer'] ?? '').toString(),
      fingerprint: (json['fingerprint'] ?? '').toString(),
      members: members,
      hashes: hashes,
    );
  }

  final String rel;
  final String section;
  final String name;
  final int size;
  final int mtime;
  final String layer;

  /// Sorted `crc32:size` list of the image members (read from the ZIP central
  /// directory without decoding).
  final String fingerprint;
  final List<FullIndexMember> members;

  /// Hash maps ready for `PirateFinderIndex.matchByHashes` (raw + file).
  final List<Map<String, dynamic>> hashes;
}

/// One image member (`.msa`/`.st`/`.stx`) of a ZIP.
class FullIndexMember {
  FullIndexMember({
    required this.name,
    required this.format,
    required this.crc32,
    required this.size,
    required this.raw,
    required this.file,
    required this.hashes,
  });

  factory FullIndexMember.fromJson(Map<String, dynamic> json) {
    final raw = (json['raw'] as Map<String, dynamic>?);
    final file = (json['file'] as Map<String, dynamic>?);
    return FullIndexMember(
      name: (json['name'] ?? '').toString(),
      format: (json['format'] ?? '').toString(),
      crc32: (json['crc32'] ?? '').toString(),
      size: (json['size'] as num?)?.toInt(),
      raw: raw,
      file: file,
      hashes: [?raw, ?file],
    );
  }

  final String name;
  final String format;
  final String crc32;
  final int? size;

  /// Decoded disk-image hashes (TOSEC `.st`), when present.
  final Map<String, dynamic>? raw;

  /// Stored member hashes (`.msa`/`.stx`), when present.
  final Map<String, dynamic>? file;

  final List<Map<String, dynamic>> hashes;
}
